nextflow_process {

    name "Test Process SUMMARIZEDEXPERIMENT_SUMMARIZEDEXPERIMENT"
    script "../main.nf"
    process "SUMMARIZEDEXPERIMENT_SUMMARIZEDEXPERIMENT"

    tag "modules"
    tag "modules_nfcore"
    tag "custom/tx2gene"
    tag "tximeta"
    tag "tximeta/tximport"
    tag "summarizedexperiment"
    tag "summarizedexperiment/summarizedexperiment"

    test("saccharomyces_cerevisiae - multi_matrix - rowdata - coldata - unify summarized experiment") {

        config "./unify.config"

        def kallisto
        setup {
            // params.modules_testdata_base_path is null outside the process string, so use the same env var and default as tests/config/nf-test.config
            def modules_testdata_base_path = System.getenv('NXF_MODULES_TESTDATA_BASE') ?: 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/'
            kallisto = extract(modules_testdata_base_path + 'genomics/eukaryotes/saccharomyces_cerevisiae/kallisto_results.tar.gz').resolve('kallisto_results')
            run("CUSTOM_TX2GENE") {
                script "../../../custom/tx2gene/main.nf"
                process {
                    """
                    input[0] = [
                    [ id:'test'], // meta map
                    file(params.modules_testdata_base_path + "genomics/eukaryotes/saccharomyces_cerevisiae/genome_gfp.gtf", checkIfExists: true)
                    ]
                    input[1] = [ [ id:'test' ], file('${kallisto}').listFiles().collect() ]
                    input[2] = 'kallisto'
                    input[3] = 'gene_id'
                    input[4] = 'gene_name'
                    """
                }
            }
            run("TXIMETA_TXIMPORT") {
                script "../../../tximeta/tximport/main.nf"
                process {
                    """
                    input[0] = [ [ id:'test' ], file('${kallisto}').listFiles().collect() ]
                    input[1] = CUSTOM_TX2GENE.out.tx2gene
                    input[2] = 'kallisto'
                    """
                }
            }
        }

        when {
            process {
                """
                input[0] = TXIMETA_TXIMPORT.out.counts_gene
                        .join(TXIMETA_TXIMPORT.out.counts_gene_length_scaled)
                        .join(TXIMETA_TXIMPORT.out.counts_gene_scaled)
                        .join(TXIMETA_TXIMPORT.out.lengths_gene)
                        .join(TXIMETA_TXIMPORT.out.tpm_gene)
                        .map{tuple(it[0], [it[1], it[2], it[3], it[4], it[5]])}

                input[1] = CUSTOM_TX2GENE.out.tx2gene
		input[2] = [
                    [ id:'gene'], // meta map
                    file(params.modules_testdata_base_path + "genomics/eukaryotes/saccharomyces_cerevisiae/samplesheet.csv", checkIfExists: true)
                ]
                """
            }
        }

        then {
            // Citation lines with quotes or accented names render differently under C and UTF-8 locales
            def loglines = path(process.out.log[0][1]).readLines()[3..12]

            assertAll(
                { assert process.success },
                { assert snapshot(loglines).md5().match("gene_log_multi_matrix_rowdata_coldata_unify") },
                { assert snapshot(process.out.versions).match('versions_multi_matrix_rowdata_coldata_unify') }
            )
        }
    }

